  'Android keeps counting in its step sensor while the app sleeps; the steps arrive the next time MAHDI-JYM reads it. On iPhone, today’s total is filled in from the motion history.': 'Android продолжает считать в датчике шагов, пока приложение спит; шаги появятся, когда MAHDI-JYM в следующий раз его прочитает. На iPhone сегодняшняя сумма дополняется из истории движения.',
  'Browsers only deliver motion data while the page is open and on screen. For all-day counting, install the Android app.': 'Браузеры передают данные движения только при открытой и видимой странице. Для подсчёта весь день установите приложение для Android.',
  'Stride length': 'Длина шага',
  'Estimated: {0} cm': 'Расчётная: {0} см',
  'Step notification': 'Уведомление о шагах',
  'Stays in your notifications while counting, updated as you walk.': 'Остаётся в уведомлениях во время подсчёта и обновляется на ходу.',
  'Vibrate every 1,000 steps': 'Вибрация каждые 1000 шагов',
  'Celebrations': 'Празднования',
  'A 5-second cheer at every 1,000 steps and at your goal.': '5-секундное ликование каждые 1000 шагов и при достижении цели.',
  'GPS speed': 'Скорость по GPS',
  'More accurate outdoors. Your location stays on this device.': 'Точнее на улице. Ваше местоположение остаётся на этом устройстве.',
  '{0} day streak': '{0} день подряд',
  '{0} days streak': '{0} дн. подряд',
