  'Passkeys don’t work inside an embedded preview. Open MAHDI-JYM in its own tab.': 'Ключи доступа не работают во встроенном предпросмотре. Откройте MAHDI-JYM в отдельной вкладке.',
  'The passkey was cancelled or timed out. Try again.': 'Ключ доступа отменён или истекло время ожидания. Попробуйте ещё раз.',
  'This device already has a passkey for MAHDI-JYM — sign in with it instead.': 'На этом устройстве уже есть ключ доступа для MAHDI-JYM — войдите с ним.',
  'Passkeys need the app to be opened at its own https address.': 'Для ключей доступа приложение нужно открыть по его собственному https-адресу.',
  'This page is shown inside a preview frame, where browsers block passkeys. Open it in its own tab to sign in or create a profile — or continue without an account.': 'Эта страница показана в рамке предпросмотра, где браузеры блокируют ключи доступа. Откройте её в отдельной вкладке, чтобы войти или создать профиль, — или продолжайте без аккаунта.',
