  'The reminder’s “Drank it” button and the “+” on the step notification add one of these.': 'Кнопка «Выпил» в напоминании и «+» в уведомлении о шагах добавляют одну такую порцию.',
  'Daily goal': 'Дневная цель',
  'About 33 ml per kg of body weight — {0} ml for {1} kg. More on hot days and training days.': 'Около 33 мл на кг веса — {0} мл при {1} кг. Больше в жаркие и тренировочные дни.',
  'Log your body weight for a personal recommendation (about 33 ml per kg).': 'Запишите вес, чтобы получить персональную рекомендацию (около 33 мл на кг).',
  'Recommended': 'Рекомендуется',
