  'Arrive with the app closed, with today’s water and steps and a short exercise. Skipped once the goal is reached.': 'Приходят при закрытом приложении, с сегодняшней водой и шагами и коротким упражнением. Пропускаются, когда цель достигнута.',
  'In the browser, reminders appear while MAHDI-JYM is open. Install the Android app for reminders with the app closed.': 'В браузере напоминания появляются, пока MAHDI-JYM открыт. Установите приложение для Android, чтобы получать их при закрытом приложении.',
