  'Suggest an exercise': 'Предлагать упражнение',
  'A short walk after sitting still or when behind on steps, else a quick move like “{0}”.': 'Короткая прогулка после долгого сидения или при отставании по шагам, иначе быстрое упражнение, например «{0}».',
  'Send a test reminder': 'Отправить тестовое напоминание',
