  'Full screen, also with the app closed': 'На весь экран, даже при закрытом приложении',
  'Allowed': 'Разрешено',
  'Not allowed': 'Не разрешено',
  'When a goal is reached with the app closed, Android shows the celebration over the lock screen. To see it on top of other apps too, allow “Display over other apps”.': 'Когда цель достигнута при закрытом приложении, Android показывает праздник поверх экрана блокировки. Чтобы видеть его и поверх других приложений, разрешите «Поверх других приложений».',
  'Full screen, with confetti and a fanfare, at every 1,000 steps and at your goal.': 'На весь экран, с конфетти и фанфарами, каждые 1000 шагов и при достижении цели.',
  'Full screen with the app closed': 'На весь экран при закрытом приложении',
  'At your step goal and your water goal — with a picture notification.': 'При цели по шагам и по воде — с уведомлением-картинкой.',
