  // 2.6 — Google account, automatic water goal, water panel, workout reminders
  'Google sign-in isn’t set up for this version of the app yet. Your data stays on this phone for now.': 'Вход через Google ещё не настроен для этой версии приложения. Пока данные остаются на этом телефоне.',
  'No connection to Google. Check the internet and try again.': 'Нет связи с Google. Проверьте интернет и попробуйте снова.',
  'Google Drive access wasn’t allowed, so nothing can be saved to the account.': 'Доступ к Google Диску не разрешён, поэтому в аккаунт ничего не сохранить.',
  'Google Play services aren’t available on this phone.': 'Сервисы Google Play недоступны на этом телефоне.',
  'Google sign-in didn’t work. Try again, or keep your data on this phone.': 'Не удалось войти через Google. Попробуйте снова или храните данные на этом телефоне.',
  'Keep your progress safe': 'Сохраните свой прогресс',
  'Sign in with a Google account that’s already on this phone — no password — and every workout, step, glass of water and setting is saved to it. Or keep everything on this phone.': 'Войдите с аккаунтом Google, который уже есть на этом телефоне, — без пароля, — и каждая тренировка, шаг, стакан воды и настройка будут сохраняться в нём. Или храните всё на этом телефоне.',
  'Continue with Google': 'Продолжить с Google',
  'Choose one of the accounts on this phone': 'Выберите один из аккаунтов на этом телефоне',
  'Save on this phone': 'Хранить на этом телефоне',
  'Nothing leaves the phone. Back up anytime from Settings.': 'Ничего не покидает телефон. Резервную копию можно сделать в Настройках.',
  'Saved in a private app folder in your Google Drive that only MAHDI-JYM can see. Sign out anytime in Settings.': 'Хранится в закрытой папке приложения на вашем Google Диске, которую видит только MAHDI-JYM. Выйти можно в любой момент в Настройках.',
  'Connecting your account…': 'Подключаем аккаунт…',
  'Choose an account in the window that appears.': 'Выберите аккаунт в появившемся окне.',
  'Data found in your account': 'В аккаунте найдены данные',
  '{0} already has MAHDI-JYM data, and this phone has some too. Which one do you want to keep?': 'В {0} уже есть данные MAHDI-JYM, и на этом телефоне тоже. Какие оставить?',
  'Use the account’s data': 'Взять данные аккаунта',
  'Keep this phone’s data': 'Оставить данные телефона',
