  'Signed in': 'Вход выполнен',
  'Your data was restored from the account.': 'Данные восстановлены из аккаунта.',
  'Signed in — the first save happens as soon as there’s a connection.': 'Вход выполнен — первое сохранение произойдёт при появлении связи.',
  'Everything is saved to your account from now on, automatically.': 'Теперь всё автоматически сохраняется в вашем аккаунте.',
  'Never': 'Никогда',
