  'Sign out of Google?': 'Выйти из Google?',
  'Your data stays on this phone and in your Google account. Changes are no longer saved to the account.': 'Данные остаются на этом телефоне и в аккаунте Google. Изменения больше не сохраняются в аккаунт.',
  'Signed out': 'Вы вышли',
