  'Sign in with a Google account that’s already on this phone — no password. Everything is saved to a private app folder in its Google Drive.': 'Войдите с аккаунтом Google, который уже есть на этом телефоне, — без пароля. Всё сохраняется в закрытой папке приложения на его Google Диске.',
  'Sign in with Google': 'Войти через Google',
