  'Workouts, plan, steps, water, body weight and settings are saved to a private app folder in your Google Drive. Progress photos stay on this phone.': 'Тренировки, план, шаги, вода, вес тела и настройки сохраняются в закрытой папке приложения на вашем Google Диске. Фото прогресса остаются на этом телефоне.',
