  'For every day — or set a time per day below': 'Для всех дней — или задайте время для каждого дня ниже',
  'Reminds you on days that have a routine planned and not yet trained — with the exercises, about how long it takes and your step goal in the same notification.': 'Напоминает в дни с запланированной программой, если тренировки ещё не было, — с упражнениями, примерной длительностью и целью по шагам в одном уведомлении.',
  '{0} ml per 1,000 steps after the first {1}, and {2} ml per minute of training. Updates through the day — also in the notification.': '{0} мл на каждые 1000 шагов после первых {1} и {2} мл за минуту тренировки. Обновляется в течение дня — и в уведомлении.',
