  'Tap a glass, cup, can or bottle in the notification to add it, Undo to take the last one back, Edit to open this screen — all with the app closed.': 'Нажмите стакан, чашку, банку или бутылку в уведомлении, чтобы добавить, «Отменить» — чтобы убрать последнее, «Изменить» — чтобы открыть этот экран, даже при закрытом приложении.',
