  // 2.8 — Google account without setup (Android Backup)
  'Welcome back — your data was restored from your Google account': 'С возвращением — ваши данные восстановлены из аккаунта Google',
  'Google Drive isn’t set up for this version of the app yet — your data is still saved to your Google account through Android Backup.': 'Google Диск ещё не настроен для этой версии приложения — но данные всё равно сохраняются в аккаунт Google через резервное копирование Android.',
  'Saved privately to your Google account — only MAHDI-JYM can read it. Sign out anytime in Settings.': 'Хранится приватно в вашем аккаунте Google — читать может только MAHDI-JYM. Выйти можно в любой момент в Настройках.',
  'Everything is saved to your Google account automatically through Android Backup, and comes back when you install MAHDI-JYM again.': 'Всё автоматически сохраняется в аккаунт Google через резервное копирование Android и возвращается при повторной установке MAHDI-JYM.',
  'Now saved to Google Drive': 'Теперь сохраняется в Google Диск',
  'Your data stays on this phone. Changes are no longer saved to your Google account.': 'Ваши данные остаются на этом телефоне. Изменения больше не сохраняются в аккаунт Google.',
  'Sign in with a Google account that’s already on this phone — no password. Everything is then saved to that account automatically.': 'Войдите с аккаунтом Google, который уже есть на этом телефоне, — без пароля. Затем всё автоматически сохраняется в этот аккаунт.',
  'Workouts, plan, steps, water, body weight and settings are saved through Android Backup to your Google account. Android uploads it in the background, usually within a few hours, and puts it back when you install MAHDI-JYM again or on a new phone. Progress photos stay on this phone.': 'Тренировки, план, шаги, вода, вес тела и настройки сохраняются в аккаунт Google через резервное копирование Android. Android загружает их в фоне, обычно в течение нескольких часов, и возвращает при повторной установке MAHDI-JYM или на новом телефоне. Фото прогресса остаются на этом телефоне.',
  'Google Drive': 'Google Диск',
  'Android Backup': 'Резервное копирование Android',
