  "Google Drive isn’t switched on for this app yet": "Google Drive для этого приложения ещё не включён",
  "That needs a one-time setup in Google Cloud by the app’s owner. Until then everything is saved through Android Backup — nothing is lost.": "Для этого владелец приложения должен один раз настроить Google Cloud. До тех пор всё сохраняется через Android Backup — ничего не теряется.",
