  "Once a day, when something changed, a full copy is kept on this phone and in Google Drive. The newest ones are kept; older ones are removed.": "Раз в день, если что-то изменилось, полная копия сохраняется на этом телефоне и в Google Drive. Новые остаются, старые удаляются.",
  "Once a day, when something changed, a full copy is kept on this phone. The newest ones are kept; older ones are removed.": "Раз в день, если что-то изменилось, полная копия сохраняется на этом телефоне. Новые остаются, старые удаляются.",
  "Save a version every day": "Сохранять версию каждый день",
