  "No versions in Drive yet.": "В Drive пока нет версий.",
  "A version is a full copy: workouts, plan, routines, steps, water, body weight, health log and settings. Progress photos stay where they are. For a copy you can keep anywhere, use Export in Settings.": "Версия — это полная копия: тренировки, план, программы, шаги, вода, вес, журнал здоровья и настройки. Фото прогресса остаются на месте. Для копии, которую можно хранить где угодно, используйте экспорт в настройках.",
  "Open console.cloud.google.com with your Google account and create a project (any name).": "Откройте console.cloud.google.com в своём аккаунте Google и создайте проект (с любым именем).",
  "APIs & Services → Library → search “Google Drive API” → Enable.": "APIs & Services → Library → найдите «Google Drive API» → Enable.",
  "OAuth consent screen → External → fill in the app name and your email → add the scope …/auth/drive.appdata → add your own account as a test user.": "OAuth consent screen → External → укажите название приложения и свою почту → добавьте область …/auth/drive.appdata → добавьте свой аккаунт как тестового пользователя.",
  "Credentials → Create credentials → OAuth client ID → Android → paste the package name and SHA-1 below.": "Credentials → Create credentials → OAuth client ID → Android → вставьте имя пакета и SHA-1 ниже.",
  "Wait about 5 minutes, then come back here and tap Try again. Nothing changes in the app itself.": "Подождите около 5 минут, вернитесь сюда и нажмите «Повторить». В самом приложении ничего не меняется.",
  "Switch on Google Drive": "Включить Google Drive",
  "Only needed once, by the app’s owner. Saving through Android Backup keeps working the whole time.": "Нужно один раз, владельцу приложения. Сохранение через Android Backup всё это время работает.",
  "Package name": "Имя пакета",
