  // 4.1 — Google check, today’s workout linked to the scale
  "The Google Drive API is switched off in the Cloud project": "Google Drive API отключён в проекте Cloud",
  "In Google Cloud: APIs & Services → Library → Google Drive API → Enable. Then test again in a few minutes.": "В Google Cloud: API и сервисы → Библиотека → Google Drive API → Включить. Затем проверьте снова через несколько минут.",
  "Google doesn’t know this app yet": "Google пока не знает это приложение",
  "Create an Android OAuth client in Google Cloud with exactly the package name and SHA-1 shown here. Wait about 5 minutes, then test again.": "Создайте в Google Cloud OAuth-клиент Android с точно таким именем пакета и SHA-1, как здесь. Подождите около 5 минут и проверьте снова.",
  "Access to Google Drive wasn’t allowed": "Доступ к Google Drive не разрешён",
  "Tap Test Google Drive and choose Allow. While the app is in testing, your account must be listed as a test user on the OAuth consent screen.": "Нажмите «Проверить Google Drive» и выберите «Разрешить». Пока приложение в тестировании, ваш аккаунт должен быть тестовым пользователем на экране согласия OAuth.",
  "Google refused access for this account": "Google отказал в доступе для этого аккаунта",
  "On the OAuth consent screen: user type External, your account added as a test user, and the scope …/auth/drive.appdata added. Then test again.": "На экране согласия OAuth: тип пользователей «Внешний», ваш аккаунт в тестовых пользователях и добавлена область …/auth/drive.appdata. Затем проверьте снова.",
  "No connection to Google": "Нет связи с Google",
