  "Save to your Google Drive too": "Сохранять и в Google Диск",
  "Your data is already saved to your Google account through Android Backup. Add a file in your own Google Drive that you can see, and that is updated with every change — no setup.": "Ваши данные уже сохраняются в аккаунт Google через резервное копирование Android. Добавьте файл в свой Google Диск — он виден вам и обновляется при каждом изменении, без настройки.",
