  "Choose the place in the window that appears.": "Выберите место в появившемся окне.",
  "Data found in the file": "В файле найдены данные",
  "The file has MAHDI-JYM data, and this phone has some too. Which one do you want to keep?": "В файле есть данные MAHDI-JYM, и на этом телефоне тоже. Какие оставить?",
  "Use the file’s data": "Взять данные из файла",
  "Welcome back": "С возвращением",
  "Your data was restored from Google Drive. Every change is saved back to the same file.": "Данные восстановлены из Google Диска. Каждое изменение сохраняется в тот же файл.",
