  "Your data stays on this phone and in your Google Drive. Changes are no longer saved to your Google account or to the Drive file.": "Данные остаются на этом телефоне и в Google Диске. Изменения больше не сохраняются ни в аккаунт Google, ни в файл на Диске.",
  "Every change is written to your file a moment after you make it. Sign in with Google as well to also keep a copy through Android Backup.": "Каждое изменение записывается в файл через мгновение. Войдите также через Google, чтобы хранить копию и в резервной копии Android.",
  "Saved to your file": "Сохранено в вашем файле",
  "Drive app folder": "Папка приложения на Диске",
  "Google Drive file": "Файл на Google Диске",
  "Workouts, plan, steps, water, body weight and settings are saved to the file in your Google Drive and through Android Backup to your Google account. Progress photos stay on this phone.": "Тренировки, план, шаги, вода, вес и настройки сохраняются в файл на Google Диске и через резервное копирование Android в аккаунт Google. Фото прогресса остаются на этом телефоне.",
