  "Phone": "Телефон",
  "In the phone settings the notifications are grouped: steps & activity, water, schedule & meals, workouts, health.": "В настройках телефона уведомления сгруппированы: шаги и активность, вода, расписание и питание, тренировки, здоровье.",
  "Sounds, banners and lock screen for each kind": "Звуки, баннеры и экран блокировки для каждого вида",
  "Send a test notification": "Отправить тестовое уведомление",
