  "Reminders that show everything": "Напоминания, где видно всё",
  "Arrange everything yourself — school, meals, drinks, work, prayer — on the days you choose, with an end time and your own notes.": "Составьте всё сами — школу, еду, напитки, работу, молитву — по выбранным дням, со временем окончания и своими заметками.",
  "School Sunday to Thursday, 7:30 to 12:40, then lunch, rest, homework, work, drinks and dinner — and a calmer weekend.": "Школа с воскресенья по четверг, 7:30–12:40, потом обед, отдых, домашка, работа, напитки и ужин — и спокойные выходные.",
  "Each reminder shows the time, your notes and the food and drinks you chose with their calories — with Done ✓ and In 10 min.": "Каждое напоминание показывает время, заметки, выбранную еду и напитки с калориями — с «Готово ✓» и «Через 10 мин».",
  "Colas, lemon-lime, fruit sodas, malt and energy drinks and homemade mojitos — in cans, bottles and glasses of every size, with sugar in teaspoons.": "Колы, лимонады, фруктовая газировка, солодовые и энергетики, домашний мохито — в банках, бутылках и стаканах любого размера, сахар в чайных ложках.",
  "Pistachios, almonds, walnuts, cashews, the seeds you crack and kerzat — raw, roasted or salted, by the handful, with what each is good for.": "Фисташки, миндаль, грецкие орехи, кешью, семечки и керзат — сырые, жареные или солёные, горстями, с пользой каждого.",
  "All notifications in one place": "Все уведомления в одном месте",
