  "Smoother everywhere": "Плавнее везде",
  "Tidier tools, smoother animations and many small fixes — drinks are now logged to the right meal.": "Аккуратнее инструменты, плавнее анимации и много мелких исправлений — напитки теперь записываются в нужный приём пищи.",
