  "Regular colas are high in sugar and have some caffeine. The zero versions have no calories.": "В обычной коле много сахара и немного кофеина. В версиях зеро нет калорий.",
  "Lemon & lime": "Лимон и лайм",
  "No caffeine, but just as sweet as cola — the diet versions have no sugar.": "Без кофеина, но так же сладко, как кола, — в диетических версиях сахара нет.",
  "Fruit sodas": "Фруктовые газировки",
  "Coloured and sweet, usually with no real fruit. Sparkling water with fresh juice is a lighter choice.": "Яркие и сладкие, обычно без настоящих фруктов. Газированная вода со свежим соком — вариант полегче.",
  "Soda & sparkling water": "Содовая и газированная вода",
  "Soda and sparkling water have no calories. Tonic water and ginger ale are sweetened.": "В содовой и газированной воде нет калорий. Тоник и имбирный эль подслащены.",
  "Malt drinks 0.0%": "Солодовые напитки 0,0%",
  "Malt drinks have no alcohol. The flavoured ones are as sweet as soft drinks; the classic is lighter.": "В солодовых напитках нет алкоголя. Ароматизированные сладкие, как газировка, классический — легче.",
  "Energy drinks": "Энергетики",
  "Lots of caffeine and sugar. Not for children, pregnancy or anyone sensitive to caffeine — one can a day at most.": "Много кофеина и сахара. Не для детей, беременных и чувствительных к кофеину — не больше одной банки в день.",
  "Homemade sodas": "Домашние газировки",
  "Made at home with soda water, fresh lemon and mint — you decide how sweet. Values assume a little sugar.": "Делаются дома из содовой, свежего лимона и мяты — сладость решаете вы. Значения рассчитаны с небольшим количеством сахара.",
  "High in caffeine — not for children, pregnancy or anyone sensitive to caffeine. Never mix it with alcohol, and not during hard exercise in the heat.": "Много кофеина — не для детей, беременных и чувствительных к кофеину. Никогда не смешивайте с алкоголем и не пейте при тяжёлой нагрузке в жару.",
